package com.boutique.shipping.messaging;import com.boutique.shipping.repository.ShippingOutboxRepository;import org.slf4j.*;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.beans.factory.annotation.Value;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component public class ShippingOutboxPublisher{private static final Logger log=LoggerFactory.getLogger(ShippingOutboxPublisher.class);private final ShippingOutboxRepository repo;private final KafkaTemplate<String,String>kafka;private final RabbitTemplate rabbit;private final String topic;public ShippingOutboxPublisher(ShippingOutboxRepository r,KafkaTemplate<String,String>k,RabbitTemplate q,@Value("${app.kafka.shipping-events-topic}")String t){repo=r;kafka=k;rabbit=q;topic=t;}@Scheduled(fixedDelayString="${app.outbox.publish-delay-ms:1000}")@Transactional public void publish(){for(var e:repo.lockBatch(50)){if(e.getKafkaPublishedAt()==null)try{kafka.send(topic,e.getAggregateId().toString(),e.getPayload()).join();e.kafkaPublished();}catch(Exception x){log.error("SHIPPING_OUTBOX_KAFKA_FAILED eventId={}",e.getId(),x);}if(e.getRabbitPublishedAt()==null)try{rabbit.convertAndSend(RabbitTopologyConfig.EXCHANGE,"shipping.shipment_created",e.getPayload());e.rabbitPublished();}catch(Exception x){log.error("SHIPPING_OUTBOX_RABBIT_FAILED eventId={}",e.getId(),x);}}}}
